// atf_layout.cs - firmware layout: finds every firmware location this tool uses, in whatever firmware build it is
// given, so the patcher and the digital twin are not tied to one XP-Pen release.
//
// Every patch site, firmware function and table the tool touches is written in the source by its address in the
// reference build (2025-02-14, "February"): Fw.A(0x0800398C). Each such address is a SYMBOL with a byte signature
// (atf_symbols.cs, generated by tools/mksig.py). The signature is the code around the location with every byte
// that legitimately differs between builds masked out: call/branch encodings, literal-pool offsets, pointers into
// flash, and the bytes this tool itself rewrites (so an already-built image resolves too). For a given firmware the
// layout searches each signature in the firmware region:
//   - exactly one match  -> resolved: the location in THIS firmware;
//   - none, or several   -> unresolved. Never guessed. Every modification that needs it is reported incompatible by
//                           the compatibility check and is not built (not even when forced).
// For the builds the signatures were verified on (February and December 2025) the resolved addresses are also checked
// against a stored table; a difference there means the image is not what its build string says.
using System;
using System.Text;
using Gd32Emu;

namespace AnargonsTabletTools
{
    public class KnownBuild
    {
        public string build;
        public int end;          // firmware end (where the free flash starts)
        public long crc;         // CRC-32 of BASE..end of the untouched stock image
        public int col;          // column of this build in the symbol table (0 February, 1 December)
        public KnownBuild(string b, int e, long c, int k) { build = b; end = e; crc = c; col = k; }
    }

    public class Layout
    {
        public const int BASE = 0x08003800, FLASH_END = 0x08010000;
        public const string MISSING = "firmware location not found: ";
        public static readonly KnownBuild[] KNOWN = new KnownBuild[] {
            new KnownBuild("2025-02-14_release001", 0x0800C7CC, 0xB65DB693L, 0),
            new KnownBuild("2025-12-23_release001", 0x0800C7D8, 0x4525CA51L, 1) };

        public int end = -1;                   // firmware end from the scatter-load table (-1: not found)
        public bool endFromTable;              // the end came from the firmware's own table (else: known build, or none)
        public int searchEnd;                  // signatures are searched in BASE..searchEnd
        public KnownBuild known = null;        // set when the build string names a verified build
        public string mismatch = null;         // known build whose resolved addresses differ from the stored table
        public int[] feb, at;                  // sorted February addresses -> address in this firmware (-1 unresolved)
        public int[] hits;                     // signature matches found (0 missing, 1 resolved, >1 ambiguous)
        byte[] d; int off, n;                  // the firmware bytes (BASE at d[off]), n bytes

        // ---------------------------------------------------------------- signatures (parsed once)
        // R42: a signature holds no firmware bytes. It is the window's mask, a 16-bit quick check of its first four
        // fixed bytes (Quick16) and the first 64 bits of the SHA-256 of the window with every masked byte set to 0.
        // A position matches when both agree; the quick check only saves hashing every position.
        static int[] sFeb, sOff, sDec, sQuick;
        static long[] sFp;
        static byte[][] sMask;
        static int[][] sFirst;                 // the window offsets of the first four fixed bytes
        // R45-rc3: signatures a patcher package adds for its own locations (tools/mksig.py run on its sources; the same
        // line format as FwSigs.S). A location this tool already signs must come with the same line.
        static string[] sExtra = new string[0];
        public static void AddSignatures(string[] lines)
        {
            for (int i = 0; i < lines.Length; i++)
            {
                string[] p = P.Split(lines[i], '|');
                if (p.Length != 6 || P.Len(p[0]) != 8) throw new Stop("a package signature is not in the tools/mksig.py format: " + lines[i]);
                string[] all = Lines();
                bool dup = false;
                for (int k = 0; k < all.Length; k++)
                {
                    if (!P.Eq(P.Split(all[k], '|')[0], p[0])) continue;
                    if (!P.Eq(all[k], lines[i])) throw new Stop("a package signature for " + p[0] + " differs from the one already known");
                    dup = true;
                }
                if (dup) continue;
                string[] e = new string[sExtra.Length + 1];
                for (int k = 0; k < sExtra.Length; k++) e[k] = sExtra[k];
                e[sExtra.Length] = lines[i];
                sExtra = e;
            }
            sFeb = null; last = null;           // parse again, and resolve every firmware again
            Parse();
        }
        // every signature, sorted by February address (Idx searches them by halving)
        static string[] Lines()
        {
            string[] S = new string[FwSigs.S.Length + sExtra.Length];
            for (int i = 0; i < FwSigs.S.Length; i++) S[i] = FwSigs.S[i];
            for (int i = 0; i < sExtra.Length; i++) S[FwSigs.S.Length + i] = sExtra[i];
            for (int i = 1; i < S.Length; i++)
            {
                string v = S[i]; long f = F.ParseInt("0x" + P.Sub(v, 0, 8));
                int j = i - 1;
                while (j >= 0 && F.ParseInt("0x" + P.Sub(S[j], 0, 8)) > f) { S[j + 1] = S[j]; j--; }
                S[j + 1] = v;
            }
            return S;
        }
        static void Parse()
        {
            if (sFeb != null) return;
            string[] S = Lines();
            int[] fe = new int[S.Length], of = new int[S.Length], de = new int[S.Length], qu = new int[S.Length];
            long[] fp = new long[S.Length];
            byte[][] ma = new byte[S.Length][];
            int[][] fi = new int[S.Length][];
            for (int i = 0; i < S.Length; i++)
            {
                string[] p = P.Split(S[i], '|');
                fe[i] = (int)F.ParseInt("0x" + p[0]); of[i] = (int)F.ParseInt(p[1]); de[i] = (int)F.ParseInt("0x" + p[5]);
                qu[i] = (int)F.ParseInt("0x" + p[3]); fp[i] = F.ParseInt("0x" + p[4]);
                string h = p[2];
                int m = P.Len(h), nf = 0;
                ma[i] = new byte[m]; fi[i] = new int[4];
                for (int k = 0; k < m; k++)
                {
                    bool fixd = P.CharAt(h, k) == 'x';
                    ma[i][k] = fixd ? (byte)0xFF : (byte)0;
                    if (fixd && nf < 4) fi[i][nf++] = k;
                }
                if (nf < 4) throw new Stop("internal: signature " + p[0] + " has fewer than four fixed bytes");
            }
            sMask = ma; sFirst = fi; sQuick = qu; sFp = fp; sOff = of; sDec = de; sFeb = fe;
        }
        public static int Count() { Parse(); return sFeb.Length; }
        // the quick check of four bytes (tools/mksig.py quick16): the top half of their little-endian word times
        // 2654435761, modulo 2^32
        public static int Quick16(int b0, int b1, int b2, int b3)
        {
            long w = (long)(b0 & 0xFF) + ((long)(b1 & 0xFF) << 8) + ((long)(b2 & 0xFF) << 16) + ((long)(b3 & 0xFF) << 24);
            return (int)(((w * 2654435761L) & 0xFFFFFFFFL) >> 16);
        }
        // the fingerprint of the window at d[o..o+mask.Length): first 64 bits of SHA-256, masked bytes as 0
        public static long WindowFp(byte[] d, int o, byte[] mask)
        {
            byte[] w = new byte[mask.Length];
            for (int k = 0; k < w.Length; k++) w[k] = (byte)(d[o + k] & mask[k]);
            byte[] h = Sha256.Hash(w, 0, w.Length);
            long v = 0;
            for (int k = 0; k < 8; k++) v = (v << 8) + (h[k] & 0xFF);
            return v;
        }

        // ---------------------------------------------------------------- firmware end (scatter-load table)
        // The firmware's start-up code copies .data from flash using a table of 16-byte entries {load address,
        // RAM address, size, copy routine}. The last entry (zero-initialised RAM) carries the image's end as its load
        // address - the first byte the firmware does not use. -1 if no such table is in the bytes given (a truncated
        // dump: the table sits near the end of the image).
        public static int FindEnd(byte[] d, int off, int n)
        {
            for (int p = 0; p + 32 <= n; p += 4)
            {
                int k = 0, mx = -1;
                while (p + 16 * (k + 1) <= n && Entry(d, off + p + 16 * k, n)) { int ld = Machine.LE(d, off + p + 16 * k, 4); if (ld > mx) mx = ld; k++; }
                if (k >= 2 && mx > BASE + p && mx <= FLASH_END) return mx;      // may lie past n: a dump cut inside .data
            }
            return -1;
        }
        static bool Entry(byte[] d, int o, int n)
        {
            long ld = Machine.LE(d, o, 4) & 0xFFFFFFFFL, ex = Machine.LE(d, o + 4, 4) & 0xFFFFFFFFL, sz = Machine.LE(d, o + 8, 4) & 0xFFFFFFFFL, fn = Machine.LE(d, o + 12, 4) & 0xFFFFFFFFL;
            return ld >= BASE && ld < FLASH_END && ex >= 0x20000000L && ex < 0x20002000L && sz < 0x2000 && fn > BASE && fn < BASE + n;
        }

        // ---------------------------------------------------------------- resolve
        static Layout last = null;             // cache: the twin resolves the same firmware many times
        long crc;
        byte[] seen;                           // R43 review: a copy of the bytes resolved; the cache compares them, not
                                               // only the CRC-32 (two images can share a CRC-32: the host suite's fake does)
        // d[off..off+n) holds the firmware from BASE (an application image, or a full 64 KB flash with off 0x3800)
        public static Layout For(byte[] d, int off, int n, string build)
        {
            if (n > FLASH_END - BASE) n = FLASH_END - BASE;
            if (off + n > d.Length) n = d.Length - off;
            long c = Txt.Crc32(d, off, n);
            Layout l0 = last;
            if (l0 != null && l0.crc == c && l0.n == n && P.Eq(l0.build, build) && Same(l0.seen, d, off, n)) return l0;
            Layout l = new Layout();
            l.d = d; l.off = off; l.n = n; l.crc = c; l.build = build;
            l.seen = new byte[n]; P.Copy(d, off, l.seen, 0, n);
            l.Resolve();
            last = l;
            return l;
        }
        static bool Same(byte[] a, byte[] d, int off, int n)
        {
            if (a == null || a.Length != n) return false;
            for (int i = 0; i < n; i++) if (a[i] != d[off + i]) return false;
            return true;
        }
        public string build;
        void Resolve()
        {
            Parse();
            end = FindEnd(d, off, n);
            endFromTable = end > 0;
            for (int i = 0; i < KNOWN.Length; i++) if (P.Eq(build, KNOWN[i].build)) known = KNOWN[i];
            if (end < 0 && known != null) end = known.end;
            searchEnd = end > BASE ? end : BASE + n;
            if (searchEnd > BASE + n) searchEnd = BASE + n;
            int m = sFeb.Length;
            feb = new int[m]; at = new int[m]; hits = new int[m];
            for (int i = 0; i < m; i++)
            {
                feb[i] = sFeb[i];
                int h = 0, pos = -1;
                byte[] mk = sMask[i];
                int[] f4 = sFirst[i];
                int q = sQuick[i];
                long want = sFp[i];
                int lim = searchEnd - BASE - mk.Length;
                for (int p = 0; p <= lim; p += 2)
                {
                    int o = off + p;
                    if (Quick16(d[o + f4[0]], d[o + f4[1]], d[o + f4[2]], d[o + f4[3]]) != q) continue;
                    if (WindowFp(d, o, mk) != want) continue;
                    h++; pos = p; if (h > 1) break;
                }
                hits[i] = h;
                at[i] = h == 1 ? BASE + pos + sOff[i] : -1;
            }
            if (known != null)
            {
                for (int i = 0; i < m; i++)
                {
                    int want = known.col == 0 ? sFeb[i] : sDec[i];
                    if (at[i] == want) continue;
                    if (at[i] < 0 && BASE + n < known.end) continue;      // a truncated dump simply lacks it: not a mismatch
                    // the build string names a verified build but this location is elsewhere: the image is not that
                    // untouched build. Distrust the location rather than patch it (its modifications become incompatible).
                    if (mismatch == null) mismatch = known.build + ": firmware location " + F.Hx(sFeb[i], 8) + " found at " + (at[i] < 0 ? "no address" : F.Hx(at[i], 8)) + " instead of " + F.Hx(want, 8);
                    at[i] = -1;
                }
            }
        }

        // ---------------------------------------------------------------- lookups
        int Idx(int f)
        {
            int lo = 0, hi = feb.Length - 1;
            while (lo <= hi) { int mid = (lo + hi) / 2; if (feb[mid] == f) return mid; if (feb[mid] < f) lo = mid + 1; else hi = mid - 1; }
            return -1;
        }
        public bool Registered(int f) { return Idx(f) >= 0; }
        public bool Has(int f) { int i = Idx(f); return i >= 0 && at[i] >= 0; }
        // the address in this firmware of the location at February address f. Throws (MISSING) when it was not found.
        public int A(int f)
        {
            int i = Idx(f);
            if (i < 0) throw new Stop("internal: " + F.Hx(f, 8) + " is used as a firmware address but has no signature (run tools/mksig.py)");
            if (at[i] < 0) throw new Stop(MISSING + F.Hx(f, 8) + (hits[i] > 1 ? " (found more than once)" : " (not found)"));
            return at[i];
        }
        // the February address of a resolved location (-1 if a is not one)
        public int FebOf(int a) { for (int i = 0; i < at.Length; i++) if (at[i] == a) return feb[i]; return -1; }
        // the word stored at a literal-pool location (e.g. a pointer to a firmware table)
        public int Ptr(int f) { int a = A(f); return Machine.LE(d, off + a - BASE, 4); }
        public int Resolved() { int k = 0; for (int i = 0; i < at.Length; i++) if (at[i] >= 0) k++; return k; }
        public string Unresolved()
        {
            StringBuilder sb = new StringBuilder();
            bool first = true;
            for (int i = 0; i < at.Length; i++) if (at[i] < 0) { sb.Append((first ? "" : ", ") + F.Hx(feb[i], 8) + (hits[i] > 1 ? " (ambiguous)" : "")); first = false; }
            return sb.ToString();
        }
        // one-line summary of how this firmware's code moved relative to February
        public string Summary()
        {
            StringBuilder sb = new StringBuilder();
            int prev = 0x7FFFFFFF;
            bool first = true;
            for (int i = 0; i < at.Length; i++)
            {
                if (at[i] < 0) continue;
                int s = at[i] - feb[i];
                if (s != prev) { sb.Append((first ? "" : ", ") + F.Hx(feb[i], 8) + " " + (s >= 0 ? "+" : "") + F.Str(s)); prev = s; first = false; }
            }
            return F.Str(Resolved()) + "/" + F.Str(at.Length) + " firmware locations found" + (first ? "" : "; offset from the 2025-02-14 layout: " + sb.ToString());
        }
        // the same code layout as `o`: every location found in both firmwares is at the same address, and most are
        // found in both. A build of this tool keeps the layout of the stock firmware it was made from (the signatures
        // mask every byte the tool rewrites), so this tells whether two images come from the same firmware build.
        public bool SameCode(Layout o)
        {
            int both = 0;
            for (int i = 0; i < at.Length; i++) { if (at[i] < 0 || o.at[i] < 0) continue; if (at[i] != o.at[i]) return false; both++; }
            return both * 10 >= at.Length * 9;
        }
        // the verified build (Layout.KNOWN) whose stored addresses this firmware's code matches, or null
        public string KnownByCode()
        {
            Parse();
            if (Resolved() * 10 < at.Length * 9) return null;
            for (int k = 0; k < KNOWN.Length; k++)
            {
                bool ok = true;
                for (int i = 0; i < at.Length && ok; i++) if (at[i] >= 0 && at[i] != (KNOWN[k].col == 0 ? sFeb[i] : sDec[i])) ok = false;
                if (ok) return KNOWN[k].build;
            }
            return null;
        }
        public static bool IsMissing(Stop e) { return e.msg != null && P.StartsWith(e.msg, MISSING); }
    }

    // the layout of the firmware being patched (set by Build from its input). Patch code uses Fw.A(February address).
    public static class Fw
    {
        public static Layout cur = null;
        public static int A(int f) { if (cur == null) throw new Stop("internal: no firmware layout"); return cur.A(f); }
        // marks a February address that is resolved later (Has / A): no lookup here, but tools/mksig.py signs it
        public static int Sym(int f) { return f; }
        public static int Ptr(int f) { if (cur == null) throw new Stop("internal: no firmware layout"); return cur.Ptr(f); }
        public static Layout Use(byte[] app, string build) { cur = Layout.For(app, 0, app.Length, build); return cur; }
    }

    // SHA-256 (FIPS 180-4) for the signature fingerprints (R42). 32-bit words are kept in longs below 2^32 because the
    // Java translation has no unsigned types; checked against the published test vectors by the core suite.
    public static class Sha256
    {
        static readonly long[] K = new long[] {
            0x428a2f98L, 0x71374491L, 0xb5c0fbcfL, 0xe9b5dba5L, 0x3956c25bL, 0x59f111f1L, 0x923f82a4L, 0xab1c5ed5L,
            0xd807aa98L, 0x12835b01L, 0x243185beL, 0x550c7dc3L, 0x72be5d74L, 0x80deb1feL, 0x9bdc06a7L, 0xc19bf174L,
            0xe49b69c1L, 0xefbe4786L, 0x0fc19dc6L, 0x240ca1ccL, 0x2de92c6fL, 0x4a7484aaL, 0x5cb0a9dcL, 0x76f988daL,
            0x983e5152L, 0xa831c66dL, 0xb00327c8L, 0xbf597fc7L, 0xc6e00bf3L, 0xd5a79147L, 0x06ca6351L, 0x14292967L,
            0x27b70a85L, 0x2e1b2138L, 0x4d2c6dfcL, 0x53380d13L, 0x650a7354L, 0x766a0abbL, 0x81c2c92eL, 0x92722c85L,
            0xa2bfe8a1L, 0xa81a664bL, 0xc24b8b70L, 0xc76c51a3L, 0xd192e819L, 0xd6990624L, 0xf40e3585L, 0x106aa070L,
            0x19a4c116L, 0x1e376c08L, 0x2748774cL, 0x34b0bcb5L, 0x391c0cb3L, 0x4ed8aa4aL, 0x5b9cca4fL, 0x682e6ff3L,
            0x748f82eeL, 0x78a5636fL, 0x84c87814L, 0x8cc70208L, 0x90befffaL, 0xa4506cebL, 0xbef9a3f7L, 0xc67178f2L };
        static long R(long x, int n) { return ((x >> n) | (x << (32 - n))) & 0xFFFFFFFFL; }
        public static byte[] Hash(byte[] msg, int off, int n)
        {
            long[] h = new long[] { 0x6a09e667L, 0xbb67ae85L, 0x3c6ef372L, 0xa54ff53aL, 0x510e527fL, 0x9b05688cL, 0x1f83d9abL, 0x5be0cd19L };
            int total = ((n + 9 + 63) / 64) * 64;
            byte[] b = new byte[total];
            P.Copy(msg, off, b, 0, n);
            b[n] = (byte)0x80;
            long bits = (long)n * 8;
            for (int i = 0; i < 8; i++) b[total - 1 - i] = (byte)((bits >> (8 * i)) & 0xFF);
            long[] w = new long[64];
            for (int blk = 0; blk < total; blk += 64)
            {
                for (int t = 0; t < 16; t++)
                {
                    int o = blk + 4 * t;
                    w[t] = ((long)(b[o] & 0xFF) << 24) + ((b[o + 1] & 0xFF) << 16) + ((b[o + 2] & 0xFF) << 8) + (b[o + 3] & 0xFF);
                }
                for (int t = 16; t < 64; t++)
                {
                    long s0 = R(w[t - 15], 7) ^ R(w[t - 15], 18) ^ (w[t - 15] >> 3);
                    long s1 = R(w[t - 2], 17) ^ R(w[t - 2], 19) ^ (w[t - 2] >> 10);
                    w[t] = (w[t - 16] + s0 + w[t - 7] + s1) & 0xFFFFFFFFL;
                }
                long a = h[0], c1 = h[1], c2 = h[2], c3 = h[3], e = h[4], f = h[5], g = h[6], hh = h[7];
                for (int t = 0; t < 64; t++)
                {
                    long t1 = (hh + (R(e, 6) ^ R(e, 11) ^ R(e, 25)) + ((e & f) ^ ((e ^ 0xFFFFFFFFL) & g)) + K[t] + w[t]) & 0xFFFFFFFFL;
                    long t2 = ((R(a, 2) ^ R(a, 13) ^ R(a, 22)) + ((a & c1) ^ (a & c2) ^ (c1 & c2))) & 0xFFFFFFFFL;
                    hh = g; g = f; f = e; e = (c3 + t1) & 0xFFFFFFFFL; c3 = c2; c2 = c1; c1 = a; a = (t1 + t2) & 0xFFFFFFFFL;
                }
                h[0] = (h[0] + a) & 0xFFFFFFFFL; h[1] = (h[1] + c1) & 0xFFFFFFFFL; h[2] = (h[2] + c2) & 0xFFFFFFFFL; h[3] = (h[3] + c3) & 0xFFFFFFFFL;
                h[4] = (h[4] + e) & 0xFFFFFFFFL; h[5] = (h[5] + f) & 0xFFFFFFFFL; h[6] = (h[6] + g) & 0xFFFFFFFFL; h[7] = (h[7] + hh) & 0xFFFFFFFFL;
            }
            byte[] outp = new byte[32];
            for (int i = 0; i < 8; i++) for (int k = 0; k < 4; k++) outp[4 * i + k] = (byte)((h[i] >> (24 - 8 * k)) & 0xFF);
            return outp;
        }
        public static string Hex(byte[] d) { StringBuilder sb = new StringBuilder(); for (int i = 0; i < d.Length; i++) sb.Append(F.HexDigits(d[i] & 0xFF, 2, false)); return sb.ToString(); }
    }
}
